    keyTerms: [
      { term: "Democracy", definition: "Government by the people, either directly or through elected representatives (from Greek demos, 'people', and kratos, 'power')." },
      { term: "Direct democracy", definition: "A system in which citizens vote on decisions themselves, as in the Athenian Assembly." },
      { term: "Representative democracy", definition: "A system in which citizens elect representatives (such as MPs) to make decisions for them." },
      { term: "Republic", definition: "A state with no monarch, whose head of state is elected or appointed (e.g. the Roman Republic, England 1649–60, Singapore since 1965)." },
      { term: "Divine Right of Kings", definition: "The belief that monarchs are chosen by God and answer only to God." },
      { term: "Constitutional monarchy", definition: "A system in which the monarch reigns but must govern within laws made by Parliament, as established by the Bill of Rights 1689." },
      { term: "Natural rights", definition: "Rights that people have simply by being human, before any government (Locke: life, liberty and property)." },
      { term: "Abolition", definition: "Ending something by law — especially the slave trade (1807) and slavery (1833) in the British Empire." },
      { term: "Franchise / suffrage", definition: "The right to vote. 'Universal suffrage' means all adults can vote." },
      { term: "Rotten borough", definition: "A constituency with very few voters that still elected MPs, such as Old Sarum; most were abolished in 1832." },
      { term: "Chartism", definition: "A mass working-class movement (from 1838) campaigning for the six points of the People's Charter." },
      { term: "Secret ballot", definition: "Voting in private so no one can see how you voted; introduced in Britain in 1872." },
      { term: "Human rights", definition: "Rights belonging to every human being, set out in the Universal Declaration of Human Rights (1948)." },
      { term: "Apartheid", definition: "South Africa's system of racial segregation and discrimination, from 1948 until the first all-race elections in 1994." },
      { term: "Self-government", definition: "When a colony runs its own internal affairs through elected representatives, while the colonial power may keep control of defence and foreign affairs (Singapore 1959)." },
      { term: "GRC (Group Representation Constituency)", definition: "In Singapore since 1988, a constituency in which a team of MPs is elected together, including at least one member of a minority community." },
      { term: "NCMP (Non-Constituency Member of Parliament)", definition: "In Singapore since 1984, a seat offered to a best-performing losing opposition candidate so Parliament always includes some opposition members." },
      { term: "Turning point", definition: "A moment of sudden, decisive change after which things are significantly different." },
    ],
